Tool response:
Tool: move_item_to_wishlist
Description: Move Item To Wishlist
Parameters:
    {
      "type": "object",
      "properties": {
        "cart_item_id": {
          "type": "integer",
          "description": "ID of the cart item to move from cart to wishlist",
          "title": "Cart Item Id"
        },
        "note": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Optional note to add to the wishlist item",
          "title": "Note"
        }
      },
      "required": [
        "cart_item_id"
      ]
    }
